function validate(input) {
  const [{ Employee = [] }] = input;
  const ids = new Set();
  for (const [id, salary] of Employee) {
    if (id === null) return 'Every employee needs an id.';
    if (ids.has(id)) return `id ${id} appears twice in Employee.`;
    if (salary === null) return `Employee ${id} needs a salary.`;
    ids.add(id);
  }
  return null;
}

reference:
WITH distinct_salaries AS (
  SELECT DISTINCT salary
  FROM Employee
)
SELECT (
  SELECT salary
  FROM distinct_salaries
  ORDER BY salary DESC
  LIMIT 1 OFFSET 1
) AS SecondHighestSalary;

